<?php $purchasingSection='invoices';require dirname(__DIR__,2).'/components/admin/purchasing-nav.php';$labels=['draft'=>'Borrador','pending'=>'Pendiente de recepción','partial'=>'Recepción parcial','received'=>'Recibida','cancelled'=>'Cancelada']; ?>
<div class="purchasing-editor purchasing-detail"><section class="admin-page-head"><div><p class="admin-kicker">FACTURA DE COMPRA</p><h1><?= e(trim($invoice['series'].' '.$invoice['folio'])) ?></h1><p><?= e($invoice['supplier_name'].' · '.$invoice['branch_name'].' · '.$invoice['document_date']) ?></p></div><div class="admin-head-actions"><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/purchases">Volver</a><?php if($invoice['status']==='draft'&&($capabilities['purchases.edit']??false)):?><a class="admin-secondary-button" data-admin-form-link href="/admin/purchases/edit?id=<?= e($invoice['id']) ?>">Editar</a><?php endif?><?php if(in_array($invoice['status'],['pending','partial'],true)&&($capabilities['purchases.receive']??false)):?><a class="admin-primary-button" data-admin-form-link href="/admin/purchases/receipts/create?id=<?= e($invoice['id']) ?>">Recibir mercancía</a><?php endif?></div></section>
<section class="purchasing-document admin-panel"><div class="admin-panel-head"><h2>Resumen del documento</h2><span class="admin-status <?= $invoice['status']==='received'?'is-active':'' ?>"><?= e($labels[$invoice['status']]??$invoice['status']) ?></span></div><dl class="admin-definition-grid"><div><dt>Proveedor</dt><dd><?= e($invoice['supplier_name'].' · '.$invoice['supplier_code']) ?></dd></div><div><dt>Total</dt><dd><?= e('$'.$invoice['total'].' MXN') ?></dd></div><div><dt>Subtotal</dt><dd><?= e('$'.$invoice['subtotal']) ?></dd></div><div><dt>Impuestos</dt><dd><?= e('$'.$invoice['tax_amount']) ?></dd></div><?php if($invoice['fiscal_uuid']):?><div><dt>UUID capturado</dt><dd><?= e($invoice['fiscal_uuid']) ?><small>Dato manual; no validado ante SAT.</small></dd></div><?php endif?></dl><?php if($invoice['notes']):?><p class="admin-detail-copy"><?= e($invoice['notes']) ?></p><?php endif?></section>
<section class="admin-panel admin-table-panel purchasing-directory"><div class="admin-panel-head admin-padded-head"><h2>Partidas</h2></div><?php if($items===[]):?><div class="admin-empty"><strong>Sin partidas</strong><span>Agrega los conceptos documentados antes de confirmar.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>#</th><th>Variante</th><th>Facturada</th><th>Recibida</th><th>Pendiente</th><th>Costo unitario</th><th>Acciones</th></tr></thead><tbody><?php foreach($items as$item):?><tr><td data-label="#"><?= e($item['line_number']) ?></td><td data-label="Variante"><div><strong><?= e($item['description']) ?></strong><small><?= e($item['product_name'].' · '.$item['sku'].' · '.$item['variant_name']) ?></small></div></td><td data-label="Facturada"><?= e($item['invoiced_quantity'].' '.$item['symbol']) ?></td><td data-label="Recibida"><?= e($item['received_quantity'].' '.$item['symbol']) ?></td><td data-label="Pendiente"><strong><?= e($item['pending_quantity'].' '.$item['symbol']) ?></strong></td><td data-label="Costo"><?= e('$'.$item['unit_cost']) ?><?php if($item['previous_unit_cost']!==null&&$item['previous_unit_cost']!==$item['unit_cost']):?><small class="admin-stock-warning">Costo anterior: $<?= e($item['previous_unit_cost']) ?>. Revisar; no cambia precios.</small><?php endif?></td><td class="admin-actions"><?php if($invoice['status']==='draft'&&($capabilities['purchases.edit']??false)):?><form data-purchasing-form method="post" action="/admin/purchases/items/delete"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="invoice_id" value="<?= e($invoice['id']) ?>"><input type="hidden" name="item_id" value="<?= e($item['id']) ?>"><button class="admin-quiet-button" data-confirm="¿Eliminar esta partida del borrador?">Eliminar</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<?php if($invoice['status']==='draft'&&($capabilities['purchases.edit']??false)):?><section class="admin-panel purchasing-add-item"><h2>Agregar partida</h2><p class="purchasing-section-copy">Selecciona una variante y captura la cantidad y el costo que figuran en la factura.</p><?php if($variantId===null):?><form class="purchasing-variant-search" method="get" action="/admin/purchases/detail" data-admin-modal-get><input type="hidden" name="id" value="<?= e($invoice['id']) ?>"><label class="admin-field"><span>Buscar producto o SKU</span><input type="search" name="variant_q" maxlength="120" value="<?= e($variantQuery??'') ?>" placeholder="Nombre del producto o SKU"></label><button class="admin-secondary-button">Buscar</button></form><form class="admin-form" data-admin-modal-get method="get" action="/admin/purchases/detail"><input type="hidden" name="id" value="<?= e($invoice['id']) ?>"><label class="admin-field"><span>Variante</span><select name="variant_id" required><option value="">Selecciona</option><?php foreach($variants as$v):?><option value="<?= e($v['id']) ?>"><?= e($v['product_name'].' · '.$v['sku'].' · '.$v['name']) ?></option><?php endforeach?></select></label><button class="admin-secondary-button">Elegir variante</button></form><?php else:?><form data-purchasing-form class="admin-form" method="post" action="/admin/purchases/items/create"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="invoice_id" value="<?= e($invoice['id']) ?>"><input type="hidden" name="variant_id" value="<?= e($variantId) ?>"><div class="admin-form-grid"><label class="admin-field"><span>Descripción documental</span><input name="description" maxlength="300" required></label><label class="admin-field"><span>Unidad facturada</span><select name="unit_id" required><?php foreach($units as$unit):?><option value="<?= e($unit['id']) ?>"><?= e($unit['name'].' ('.$unit['symbol'].')') ?></option><?php endforeach?></select></label><label class="admin-field"><span>Cantidad</span><input name="quantity" inputmode="decimal" required></label><label class="admin-field"><span>Costo unitario MXN</span><input name="unit_cost" inputmode="decimal" required></label></div><div class="admin-head-actions"><button class="admin-primary-button">Agregar partida</button><a class="admin-secondary-button" data-admin-form-link href="/admin/purchases/detail?id=<?= e($invoice['id']) ?>">Cambiar variante</a></div></form><?php endif?></section><?php if($items!==[]&&($capabilities['purchases.confirm']??false)):?><form data-purchasing-form class="admin-panel admin-head-actions" method="post" action="/admin/purchases/confirm"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($invoice['id']) ?>"><button class="admin-primary-button" data-confirm="Al confirmar ya no podrás editar el documento. ¿Continuar?">Confirmar factura</button><span class="admin-panel-copy">La confirmación no modifica inventario; habilita la recepción física.</span></form><?php endif?><?php endif?>
<section class="admin-panel"><h2>Recepciones confirmadas</h2><?php if($receipts===[]):?><div class="admin-empty"><strong>Sin recepciones</strong><span>No existe ningún movimiento de inventario originado por esta factura.</span></div><?php else:?><ul class="admin-card-list"><?php foreach($receipts as$r):?><li><span><strong>Recepción #<?= e($r['id']) ?></strong><small><?= e($r['received_at'].' · '.$r['receiver_name']) ?></small></span><span class="admin-status is-active">Confirmada</span><p><?= e($r['item_count'].' partidas') ?><?= $r['notes']?' · '.e($r['notes']):'' ?></p></li><?php endforeach?></ul><?php endif?></section>

